const incoming = $input.first().json;
const body = incoming.body || incoming;
const requestId = String(body.request_id || '');
const original = String(body.command_id || body.text || '').trim();
const normalized = original.toLowerCase().replace(/ł/g, 'l').normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9 _.:\/-]/g, ' ').replace(/\s+/g, ' ').trim();

const rules = [
  { intent: 'voice_test', words: ['ping', 'voice_test', 'voice test', 'test petli'], action_id: 'no_action', response_text: 'Pętla VoiceLoop działa.' },
  { intent: 'open_calendar', words: ['open_calendar', 'open calendar', 'otworz kalendarz', 'kalendarz'], action_id: 'open_calendar', response_text: 'Otwieram kalendarz.' },
  { intent: 'open_browser', words: ['open_browser', 'open browser', 'otworz przegladarke'], action_id: 'open_browser', response_text: 'Otwieram przeglądarkę.' },
  { intent: 'open_chat', words: ['open_chat', 'open chat', 'otworz czat'], action_id: 'open_chat', response_text: 'Otwieram czat.' }
];

const exact = rules.find(rule => rule.words.includes(normalized));
const result = exact ? {
  schema_version: 1,
  request_id: requestId,
  intent: exact.intent,
  action_id: exact.action_id,
  args: {},
  confidence: 1,
  confirmation_required: false,
  risk: 'low',
  response_text: exact.response_text
} : {
  schema_version: 1,
  request_id: requestId,
  intent: 'unknown',
  action_id: 'unknown',
  args: {},
  confidence: 0,
  confirmation_required: false,
  risk: 'low',
  response_text: ''
};
return [{ json: result }];
